<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ValueObject\Accessor\ConsentPurposeRequiredAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the ConsentPurposeRequiredAccessor trait.
 *
 * Covers null default, string/VO assignment via withRequired,
 * getRequired/required accessors, and isRequiredChanged with/without original.
 */
class ConsentPurposeRequiredAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withRequired creates a new instance with the Required set
     * from a string value, and getRequired returns the primitive string.
     */
    public function testWithRequiredFromString(): void
    {
        // Arrange
        $holder = new ImplWithConsentPurposeRequiredAccessorUnitTest();

        // Act
        $result = $holder->withRequired(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->isRequired());
    }
    /**
     * Asserts that withrequired has access to the value object
     * from a string value, and getRequired returns the primitive string.
     */
    public function testWithRequiredFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithConsentPurposeRequiredAccessorUnitTest();

        // Act
        $result = $holder->withRequired(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->required()->value());
    }
    public function testChangedRequired(): void
    {
        // Arrange
        $holder = new ImplWithConsentPurposeRequiredAccessorUnitTest()->withRequired(true);
        $original = $holder->withRequired(true);
        $same = $holder->withRequired(true);
        $modified = $holder->withRequired(false);

        // Act
        $withSame = $original->isRequiredChanged($same);
        $withDiferent = $original->isRequiredChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithConsentPurposeRequiredAccessorUnitTest
{
    use ConsentPurposeRequiredAccessor;
}
